    /\ sd_K1 MB MSZ PAB 0x4000 (Z.of_nat NS) (Z.of_nat k) (s_mb lst) ws mA
    /\ Z.of_nat (length ws) = 0x4000 /\ firstn NS ws = map (fun s0 => Z_to_bv 64 (s_mb s0)) (sec Σk)
    /\ nth_error (sec Σk) (NS - 1) = Some lst.

